#include "Janela.h"
#include <QtWidgets>
#include <QTextStream>
#include <QFile>
static QStringList nomes={"Início","Livros","Usuários","Empréstimos","Devoluções","Reservas","Prazos e atrasos","Lembretes","Histórico","Relatórios"};
static QPushButton* botao(QString s,QLayout* l){auto b=new QPushButton(s);l->addWidget(b);return b;}
static QString texto(QJsonValue v){return v.isDouble()?QString::number(v.toInt()):v.toString();}
Janela::Janela(){setWindowTitle("SB - Sistema de Biblioteca - DEMO 1.2");resize(1120,740);setMinimumSize(850,550);auto central=new QWidget;setCentralWidget(central);auto raiz=new QVBoxLayout(central);raiz->setContentsMargins(0,0,0,0);auto barra=new QToolBar;addToolBar(barra);barra->setToolButtonStyle(Qt::ToolButtonTextBesideIcon);auto menu=menuBar()->addMenu("Biblioteca");for(int i=0;i<nomes.size();++i){auto a=menu->addAction(nomes[i]);connect(a,&QAction::triggered,this,[=]{abrir(i);});if(i<6){auto t=barra->addAction(style()->standardIcon(i==0?QStyle::SP_DirHomeIcon:QStyle::SP_FileIcon),nomes[i]);connect(t,&QAction::triggered,this,[=]{abrir(i);});}}menuBar()->addMenu("Arquivo")->addAction("Sair",this,&QWidget::close);
 auto titulo=new QLabel("  SB   Sistema de Biblioteca");titulo->setStyleSheet("background:#54268a;color:white;font:bold 24px Georgia;padding:10px;");raiz->addWidget(titulo);auto corpo=new QHBoxLayout;raiz->addLayout(corpo,1);auto lateral=new QWidget;lateral->setFixedWidth(185);lateral->setStyleSheet("QWidget{background:#54268a;color:white;} QPushButton{background:#713eaa;color:white;text-align:left;padding:10px;border:1px solid #a98bd0;}");auto nav=new QVBoxLayout(lateral);for(int i=0;i<nomes.size();++i){auto b=botao(nomes[i],nav);connect(b,&QPushButton::clicked,this,[=]{abrir(i);});}nav->addStretch();corpo->addWidget(lateral);paginas=new QStackedWidget;corpo->addWidget(paginas,1);statusBar()->showMessage("Biblioteca  |  Operador local  |  DEMO 1.2 | Dados de teste locais");setStyleSheet("QMainWindow,QWidget{background:#f1eaf8;font-family:Tahoma;font-size:13px;} QLineEdit,QComboBox,QDateEdit,QTableWidget{background:white;border:1px solid #b9a5ce;} QPushButton{background:#e9ddf7;border:1px solid #a48bbb;padding:7px 12px;} QPushButton:hover{background:#d8c3f0;} QHeaderView::section{background:#e0d0f1;border:1px solid #b9a5ce;padding:5px;} QToolBar{background:#f5effb;} QMenuBar{background:#f5effb;}");atualizar();}
void Janela::abrir(int p){paginas->setCurrentIndex(p);}
void Janela::executar(const std::function<QString()>& a){try{auto e=a();if(!e.isEmpty())QMessageBox::warning(this,"Aviso",e);else{QMessageBox::information(this,"Biblioteca","Operação concluída.");atualizar();}}catch(const std::exception& e){QMessageBox::critical(this,"Erro",e.what());}}
void Janela::cadastro(QString c,int id){auto o=biblioteca.buscar(c,id);QDialog d(this);d.setWindowTitle(c=="livros"?"Cadastro de livro":"Cadastro de usuário");auto f=new QFormLayout(&d);auto cod=new QSpinBox;cod->setRange(1,999999999);cod->setValue(id?id:1);cod->setEnabled(!id);f->addRow("Código",cod);auto n=new QLineEdit(o.value(c=="livros"?"titulo":"nome").toString());f->addRow(c=="livros"?"Título":"Nome",n);auto a=new QLineEdit(o.value(c=="livros"?"autor":"email").toString());f->addRow(c=="livros"?"Autor":"E-mail",a);auto tipo=new QComboBox(&d);tipo->addItems({"Aluno","Professor"});tipo->setCurrentText(o["tipo"].toString());if(c=="usuarios")f->addRow("Tipo",tipo);else tipo->hide();auto b=new QDialogButtonBox(QDialogButtonBox::Save|QDialogButtonBox::Cancel);f->addRow(b);connect(b,&QDialogButtonBox::accepted,&d,&QDialog::accept);connect(b,&QDialogButtonBox::rejected,&d,&QDialog::reject);if(d.exec()!=QDialog::Accepted)return;if(n->text().trimmed().isEmpty()||a->text().trimmed().isEmpty()){QMessageBox::warning(this,"Aviso","Preencha os campos.");return;}if(c=="usuarios"&&!a->text().contains('@')){QMessageBox::warning(this,"Aviso","E-mail inválido.");return;}QJsonObject r{{"codigo",cod->value()}};r[c=="livros"?"titulo":"nome"]=n->text().trimmed();r[c=="livros"?"autor":"email"]=a->text().trimmed();if(c=="usuarios")r["tipo"]=tipo->currentText();executar([&]{return biblioteca.gravar(c,r,id!=0);});}
void Janela::movimento(bool reserva){QDialog d(this);d.setWindowTitle(reserva?"Nova reserva":"Novo empréstimo");auto f=new QFormLayout(&d);auto l=new QComboBox;auto u=new QComboBox;for(auto v:biblioteca.lista("livros")){auto o=v.toObject();l->addItem(o["titulo"].toString(),o["codigo"].toInt());}for(auto v:biblioteca.lista("usuarios")){auto o=v.toObject();u->addItem(o["nome"].toString(),o["codigo"].toInt());}f->addRow("Livro",l);f->addRow("Usuário",u);auto data=new QDateEdit(QDate::currentDate(),&d);data->setCalendarPopup(true);data->setDisplayFormat("dd/MM/yyyy");if(!reserva)f->addRow("Data",data);else data->hide();auto b=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel);f->addRow(b);connect(b,&QDialogButtonBox::accepted,&d,&QDialog::accept);connect(b,&QDialogButtonBox::rejected,&d,&QDialog::reject);if(d.exec()==QDialog::Accepted)executar([&]{return reserva?biblioteca.reservar(l->currentData().toInt(),u->currentData().toInt()):biblioteca.emprestar(l->currentData().toInt(),u->currentData().toInt(),data->date());});}
void Janela::tabela(QVBoxLayout* layout,QString chave,QStringList campos,QStringList titulos,int modo){auto busca=new QLineEdit;busca->setPlaceholderText("Pesquisar por código, nome ou título...");layout->addWidget(busca);auto t=new QTableWidget(0,campos.size());t->setHorizontalHeaderLabels(titulos);t->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);t->setSelectionBehavior(QAbstractItemView::SelectRows);t->setSelectionMode(QAbstractItemView::SingleSelection);t->setEditTriggers(QAbstractItemView::NoEditTriggers);t->setAlternatingRowColors(true);layout->addWidget(t,1);for(auto v:biblioteca.lista(chave)){auto o=v.toObject();if(modo==1&&o["situacao"].toString()!="Ativo")continue;if(modo==2&&(o["situacao"].toString()!="Ativo"||QDate::fromString(o["prazo"].toString(),Qt::ISODate)>=QDate::currentDate()))continue;int row=t->rowCount();t->insertRow(row);for(int j=0;j<campos.size();++j){auto c=campos[j];QString s=texto(o.value(c));if(chave=="livros"&&c=="situacao")s=biblioteca.ocupado(o["codigo"].toInt())?"Emprestado":"Disponível";if((chave=="emprestimos"||chave=="reservas")&&(c=="livro"||c=="usuario"))s=biblioteca.nome(c=="livro"?"livros":"usuarios",o[c].toInt());if(c=="atraso")s=QString::number(qMax<qint64>(0,QDate::fromString(o["prazo"].toString(),Qt::ISODate).daysTo(QDate::currentDate())));auto item=new QTableWidgetItem(s);item->setData(Qt::UserRole,o["codigo"].toInt());t->setItem(row,j,item);}}
 connect(busca,&QLineEdit::textChanged,t,[=](QString s){for(int i=0;i<t->rowCount();++i){bool ok=false;for(int j=0;j<t->columnCount();++j)ok|=t->item(i,j)->text().contains(s,Qt::CaseInsensitive);t->setRowHidden(i,!ok);}});auto acoes=new QHBoxLayout;layout->addLayout(acoes);auto selecionado=[=](){return t->currentRow()<0?0:t->item(t->currentRow(),0)->data(Qt::UserRole).toInt();};if(chave=="livros"||chave=="usuarios"){connect(botao("Novo",acoes),&QPushButton::clicked,this,[=]{cadastro(chave);});connect(botao("Editar",acoes),&QPushButton::clicked,this,[=]{if(int id=selecionado())cadastro(chave,id);});connect(botao("Excluir",acoes),&QPushButton::clicked,this,[=]{if(int id=selecionado())if(QMessageBox::question(this,"Confirmar","Excluir registro?")==QMessageBox::Yes)executar([=]{return biblioteca.excluir(chave,id);});});}else if(chave=="reservas"){connect(botao("Nova reserva",acoes),&QPushButton::clicked,this,[=]{movimento(true);});connect(botao("Cancelar reserva",acoes),&QPushButton::clicked,this,[=]{if(int id=selecionado())executar([=]{return biblioteca.cancelarReserva(id);});});}else if(chave=="emprestimos"){connect(botao("Novo empréstimo",acoes),&QPushButton::clicked,this,[=]{movimento(false);});connect(botao("Registrar devolução",acoes),&QPushButton::clicked,this,[=]{if(int id=selecionado())executar([=]{return biblioteca.devolver(id,QDate::currentDate());});});connect(botao("Simular lembrete",acoes),&QPushButton::clicked,this,[=]{if(int id=selecionado())executar([=]{return biblioteca.lembrar(id);});});}acoes->addStretch();connect(botao("Atualizar",acoes),&QPushButton::clicked,this,[=]{atualizar();});}
void Janela::atualizar(){int atual=qMax(0,paginas->currentIndex());while(paginas->count()){auto w=paginas->widget(0);paginas->removeWidget(w);w->deleteLater();}for(int i=0;i<nomes.size();++i){auto w=new QWidget;auto l=new QVBoxLayout(w);auto h=new QLabel(nomes[i]);h->setStyleSheet("background:#7042a5;color:white;font:bold 18px Tahoma;padding:8px;");l->addWidget(h);paginas->addWidget(w);if(i==0){auto resumo=new QLabel(QString("Livros cadastrados: %1    |    Usuários: %2    |    Empréstimos registrados: %3").arg(biblioteca.lista("livros").size()).arg(biblioteca.lista("usuarios").size()).arg(biblioteca.lista("emprestimos").size()));l->addWidget(resumo);for(int j=1;j<6;++j)connect(botao(nomes[j],l),&QPushButton::clicked,this,[=]{abrir(j);});l->addStretch();}else if(i==1)tabela(l,"livros",{"codigo","titulo","autor","situacao"},{"Código","Título","Autor","Situação"});else if(i==2)tabela(l,"usuarios",{"codigo","nome","email","tipo"},{"Código","Nome","E-mail","Tipo"});else if(i==5)tabela(l,"reservas",{"codigo","livro","usuario","data"},{"Código","Livro","Usuário","Data"});else if(i==8)tabela(l,"historico",{"codigo","acao","livro","usuario","data"},{"Código","Ação","Livro","Usuário","Data"});else if(i==9){tabela(l,"livros",{"codigo","titulo","autor","situacao"},{"Código","Título","Autor","Situação"});connect(botao("Exportar acervo CSV",l),&QPushButton::clicked,this,[=]{auto p=QFileDialog::getSaveFileName(this,"Exportar", "acervo.csv","CSV (*.csv)");if(p.isEmpty())return;QFile f(p);if(!f.open(QIODevice::WriteOnly)){QMessageBox::warning(this,"Erro","Não foi possível salvar.");return;}QTextStream s(&f);s<<"Código;Título;Autor;Situação\n";for(auto v:biblioteca.lista("livros")){auto o=v.toObject();auto esc=[](QString x){return QString("\"")+x.replace("\"","\"\"")+"\"";};s<<o["codigo"].toInt()<<';'<<esc(o["titulo"].toString())<<';'<<esc(o["autor"].toString())<<';'<<(biblioteca.ocupado(o["codigo"].toInt())?"Emprestado":"Disponível")<<'\n';}});}else{if(i==7)l->addWidget(new QLabel("Demonstração: lembretes são registrados no histórico, sem envio real de e-mail."));tabela(l,"emprestimos",{"codigo","livro","usuario","data","prazo","situacao","atraso"},{"Código","Livro","Usuário","Empréstimo","Prazo","Situação","Dias atraso"},i==6?2:(i==4||i==7?1:0));}}abrir(qMin(atual,int(nomes.size())-1));}
